window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8cb385cd9a2cc803"]={"versions": [{"id": "FIG-8cb385cd9a2cc803", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert das Metamodell für das Mapping von Diagnose-Indikatoren auf Port-Ebene (<code>DiagnosticIndicatorPortMapping</code>) innerhalb der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es stellt die Verknüpfung zwischen der abstrakten Diagnosefunktionalität (<code>DiagnosticIndicator</code>) und den ausführbaren Software-Artefakten über Prozess- und Dienstabhängigkeiten (<code>Process</code>, <code>SwcServiceDependency</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist <code>DiagnosticIndicatorPortMapping</code>, das von <code>DiagnosticSwMapping</code> erbt, welches seinerseits <code>DiagnosticMapping</code> und damit <code>DiagnosticCommonElement</code> bzw. <code>ARElement</code> spezialisiert. <code>DiagnosticIndicatorPortMapping</code> referenziert über die Assoziationsrolle <code>+indicator</code> genau einen <code>DiagnosticIndicator</code> (Multiplizität <code>1</code>), der ebenfalls von <code>DiagnosticCommonElement</code> erbt und die Attribute <code>type: DiagnosticIndicatorTypeEnum [0..1]</code> sowie <code>«atpVariation» +healingCycleCounterThreshold: PositiveInteger</code> deklariert.</p>\n<p class=\"fig-p\">Des Weiteren aggregiert bzw. referenziert <code>DiagnosticIndicatorPortMapping</code>:</p>\n<ul class=\"fig-list\">\n<li>über die Assoziation <code>+process</code> (Multiplizität <code>0..1</code>, Stereotyp <code>«atpSplitable»</code>) das Modellelement <code>ProcessDesign</code> (<code>ARElement</code>), welches wiederum über <code>+design</code> (<code>0..1</code>) mit <code>Process</code> (Spezialisierung von <code>AbstractExecutionContext</code>) verknüpft ist. <code>Process</code> enthält die Attribute <code>logTraceDefaultLogLevel: LogTraceDefaultLogLevelEnum [0..1]</code>, <code>logTraceFilePath: UriString [0..1]</code>, <code>logTraceLogMode: LogTraceLogModeEnum [0..1]</code>, <code>logTraceProcessDesc: String [0..1]</code>, <code>logTraceProcessId: String [0..1]</code> und <code>preMapping: Boolean [0..1]</code>.</li>\n<li>über die Instanzreferenz <code>+swcServiceDependencyInExecutable</code> (Multiplizität <code>0..1</code>, Stereotyp <code>«instanceRef»</code>) das Element <code>SwcServiceDependency</code> (<code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>).</li>\n</ul>\n<p class=\"fig-p\"><code>SwcServiceDependency</code> besitzt eine Komposition <code>+serviceNeeds</code> mit Multiplizität <code>1</code> auf <code>ServiceNeeds</code> (<code>Identifiable</code>). Dieses wird spezialisiert durch <code>DiagnosticCapabilityElement</code>, welches die Attribute <code>audience: DiagnosticAudienceEnum [0..*]</code>, <code>diagRequirement: DiagRequirementIdString [0..1]</code> und <code>securityAccessLevel: PositiveInteger [0..1]</code> bereitstellt. Unterklasse hiervon ist <code>DiagnosticIndicatorNeeds</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die statische Zuordnungsstruktur: Zur Laufzeitkonfiguration verweist ein <code>DiagnosticIndicatorPortMapping</code> auf die funktionale Diagnose-Anforderungsdefinition (<code>DiagnosticIndicatorNeeds</code> über die Instanzreferenz auf <code>SwcServiceDependency</code>) und ordnet diese dem ausführenden Prozesskontext (<code>ProcessDesign</code> / <code>Process</code>) sowie dem logischen Diagnose-Indikator zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Modellierer im Manifest-Umfeld definiert das Modell verbindliche Konsistenzregeln:</p>\n<ul class=\"fig-list\">\n<li>Das Vorhandensein eines Diagnoseindikators (<code>+indicator</code>) ist mit Multiplizität <code>1</code> obligatorisch.</li>\n<li>Die Verknüpfung zur Software-Implementierung erfolgt über eine Instanzreferenz auf eine Dienstabhängigkeit (<code>swcServiceDependencyInExecutable</code>), die zwingend genau ein <code>ServiceNeeds</code> (hier <code>DiagnosticIndicatorNeeds</code>) kapseln muss.</li>\n<li><code>healingCycleCounterThreshold</code> unterliegt der Variabilität (<code>«atpVariation»</code>), wohingegen der Indikatortyp optional statisch typisiert ist.</li>\n<li>Die Prozesszuordnung ist splitbar (<code>«atpSplitable»</code>) und verweist auf das Design-Artefakt des Prozesses.</li>\n</ul>"}, {"id": "FIG-ba3fba9edee8e634", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert das Metamodell für das Mapping von Diagnose-Indikatoren auf Port-Ebene (<code>DiagnosticIndicatorPortMapping</code>) innerhalb der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es stellt die Verknüpfung zwischen der abstrakten Diagnosefunktionalität (<code>DiagnosticIndicator</code>) und den ausführbaren Software-Artefakten über Prozess- und Dienstabhängigkeiten (<code>Process</code>, <code>SwcServiceDependency</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist <code>DiagnosticIndicatorPortMapping</code>, das von <code>DiagnosticSwMapping</code> erbt, welches seinerseits <code>DiagnosticMapping</code> und damit <code>DiagnosticCommonElement</code> bzw. <code>ARElement</code> spezialisiert. <code>DiagnosticIndicatorPortMapping</code> referenziert über die Assoziationsrolle <code>+indicator</code> genau einen <code>DiagnosticIndicator</code> (Multiplizität <code>1</code>), der von <code>DiagnosticCommonElement</code> erbt und das Attribut <code>«atpVariation» +type: DiagnosticIndicatorTypeEnum [0..1]</code> besitzt.</p>\n<p class=\"fig-p\">Des Weiteren referenziert <code>DiagnosticIndicatorPortMapping</code>:</p>\n<ul class=\"fig-list\">\n<li>über die Assoziation <code>+process</code> (Multiplizität <code>0..1</code>, Stereotyp <code>«atpSplitable»</code>) das Element <code>ProcessDesign</code> (<code>ARElement</code>), welches über <code>+design</code> (<code>0..1</code>) mit <code>Process</code> (Spezialisierung von <code>AbstractExecutionContext</code>) assoziiert ist. <code>Process</code> deklariert die Attribute <code>logTraceDefaultLogLevel: LogTraceDefaultLogLevelEnum [0..1]</code>, <code>logTraceFilePath: UriString [0..1]</code>, <code>logTraceLogMode: LogTraceLogModeEnum [0..*]</code>, <code>logTraceProcessDesc: String [0..1]</code>, <code>logTraceProcessId: String [0..1]</code>, <code>numberOfRestartAttempts: PositiveInteger [0..1]</code> und <code>preMapping: Boolean [0..1]</code>.</li>\n<li>über die Instanzreferenz <code>+swcServiceDependencyInExecutable</code> (Multiplizität <code>0..1</code>, Stereotyp <code>«instanceRef»</code>) das Element <code>SwcServiceDependency</code> (<code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>).</li>\n</ul>\n<p class=\"fig-p\"><code>SwcServiceDependency</code> besitzt eine Komposition <code>+serviceNeeds</code> mit Multiplizität <code>1</code> auf <code>ServiceNeeds</code> (<code>Identifiable</code>), das von <code>DiagnosticCapabilityElement</code> spezialisiert wird (Attribute: <code>audience: DiagnosticAudienceEnum [0..*]</code>, <code>diagRequirement: DiagRequirementIdString [0..1]</code>, <code>securityAccessLevel: PositiveInteger [0..1]</code>). Dessen Spezialisierung ist <code>DiagnosticIndicatorNeeds</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die statische Zuordnungsstruktur: Zur Laufzeitkonfiguration verweist ein <code>DiagnosticIndicatorPortMapping</code> auf die funktionale Diagnose-Anforderungsdefinition (<code>DiagnosticIndicatorNeeds</code> über die Instanzreferenz auf <code>SwcServiceDependency</code>) und ordnet diese dem ausführenden Prozesskontext (<code>ProcessDesign</code> / <code>Process</code>) sowie dem logischen Diagnose-Indikator zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Modellierer im Manifest-Umfeld gelten folgende normative Festlegungen:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>DiagnosticIndicatorPortMapping</code> erfordert exakt einen <code>DiagnosticIndicator</code> (<code>+indicator 1</code>).</li>\n<li>Das Attribut <code>type</code> an <code>DiagnosticIndicator</code> unterliegt der Systemvariabilität (<code>«atpVariation»</code>).</li>\n<li>Das Attribut <code>logTraceLogMode</code> an <code>Process</code> erlaubt mehrere Logging-Modi (<code>0..*</code>), und <code>numberOfRestartAttempts</code> steuert optional Wiederanlaufversuche.</li>\n<li>Die Beziehung zur ausführenden Softwareinstanz verläuft über die Instanzreferenz <code>swcServiceDependencyInExecutable</code> mit einer verbindlichen <code>ServiceNeeds</code>-Definition (<code>DiagnosticIndicatorNeeds</code>).</li>\n</ul>"}, {"id": "FIG-eeb2eceb2b245eea", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert das Metamodell für das Port-Mapping von Diagnose-Indikatoren (<code>DiagnosticIndicatorPortMapping</code>) auf der AUTOSAR Adaptive Platform. Es erweitert die Struktur um explizite Port- und Schnittstellenelemente (<code>PortPrototype</code>, <code>PortInterface</code>) und deren rollenbasierte Zuweisung über <code>RoleBasedPortAssignment</code> innerhalb der Dienstabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Wurzelelement des Mappings ist <code>DiagnosticIndicatorPortMapping</code>, abgeleitet über <code>DiagnosticSwMapping</code> und <code>DiagnosticMapping</code> von <code>DiagnosticCommonElement</code> (<code>ARElement</code>). Es verweist über <code>+indicator</code> (Multiplizität <code>1</code>) auf <code>DiagnosticIndicator</code> (<code>DiagnosticCommonElement</code>, Attribut: <code>«atpVariation» +type: DiagnosticIndicatorTypeEnum [0..1]</code>).</p>\n<p class=\"fig-p\"><code>DiagnosticIndicatorPortMapping</code> assoziiert:</p>\n<ul class=\"fig-list\">\n<li>über <code>+process</code> (<code>0..1</code>, <code>«atpSplitable»</code>) das Element <code>ProcessDesign</code> (<code>ARElement</code>), das via <code>+design</code> (<code>0..1</code>) auf <code>Process</code> (<code>AbstractExecutionContext</code>, Attribute: <code>functionClusterAffiliation: String [0..1]</code>, <code>numberOfRestartAttempts: PositiveInteger [0..1]</code>, <code>preMapping: Boolean [0..1]</code>) verweist.</li>\n<li>über <code>«instanceRef» +swcServiceDependencyInExecutable</code> (<code>0..1</code>) das Element <code>SwcServiceDependency</code> (<code>AtpStructureElement</code>, <code>Identifiable</code>, <code>ServiceDependency</code>).</li>\n</ul>\n<p class=\"fig-p\"><code>SwcServiceDependency</code> aggregiert:</p>\n<ul class=\"fig-list\">\n<li>über <code>+serviceNeeds</code> (Multiplizität <code>0..1</code>) das Element <code>ServiceNeeds</code> (<code>Identifiable</code>), spezialisiert durch <code>DiagnosticCapabilityElement</code> (Attribute: <code>audience: DiagnosticAudienceEnum [0..*]</code>, <code>diagRequirement: DiagRequirementIdString [0..1]</code>, <code>securityAccessLevel: PositiveInteger [0..1]</code>) und dessen Unterklasse <code>DiagnosticIndicatorNeeds</code>.</li>\n<li>über <code>+assignedPort</code> (Multiplizität <code>0..*</code>, Stereotyp <code>«atpVariation,atpSplitable»</code>) Instanzen von <code>RoleBasedPortAssignment</code> (Attribut: <code>role: Identifier [0..1]</code>).</li>\n</ul>\n<p class=\"fig-p\"><code>RoleBasedPortAssignment</code> referenziert über <code>+portPrototype</code> (<code>0..1</code>) ein <code>PortPrototype</code> (<code>AtpBlueprintable</code>, <code>AtpPrototype</code>), spezialisiert als <code>AbstractRequiredPortPrototype</code> und <code>RPortPrototype</code>. <code>RPortPrototype</code> weist über die Assoziation <code>«isOfType» +requiredInterface</code> (<code>0..1</code>, Eigenschaft <code>{redefines atpType}</code>) auf <code>PortInterface</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>). Dieses wird über <code>DiagnosticPortInterface</code> zu <code>DiagnosticIndicatorInterface</code> spezialisiert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die statische Zuordnungsstruktur: Zur Laufzeitkonfiguration verweist ein <code>DiagnosticIndicatorPortMapping</code> auf die funktionale Diagnose-Anforderungsdefinition (<code>DiagnosticIndicatorNeeds</code> über die Instanzreferenz auf <code>SwcServiceDependency</code>) und ordnet diese dem ausführenden Prozesskontext (<code>ProcessDesign</code> / <code>Process</code>) sowie dem logischen Diagnose-Indikator zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwicklungs- und Modellierungsregeln umfassen:</p>\n<ul class=\"fig-list\">\n<li>Die funktionale Anbindung an Softwarekomponenten erfolgt über <code>RoleBasedPortAssignment</code>, wodurch Ports flexibel rollenbasiert zugeordnet und per <code>«atpVariation,atpSplitable»</code> variiert bzw. aufgespalten werden können.</li>\n<li>Die Port-Schnittstelle wird über die Redefinition von <code>atpType</code> als <code>DiagnosticIndicatorInterface</code> (spezifisches <code>PortInterface</code>) typisiert.</li>\n<li>Die Komposition <code>+serviceNeeds</code> an <code>SwcServiceDependency</code> ist nun optional (<code>0..1</code>).</li>\n<li>An <code>Process</code> sind Logging-Attribute durch <code>functionClusterAffiliation</code> abgelöst.</li>\n</ul>"}, {"id": "FIG-54eaaa4e5cd932df", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Klassendiagramm stellt das vereinfachte Metamodell für <code>DiagnosticIndicatorPortMapping</code> auf der AUTOSAR Adaptive Platform dar. Die Zuordnung verbindet das Diagnose-Port-Mapping direkt mit dem Required-Port des Executables (<code>RPortPrototype</code>) und dem Diagnose-Indikator, entkoppelt von der <code>SwcServiceDependency</code>- und <code>ServiceNeeds</code>-Hierarchie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><code>DiagnosticIndicatorPortMapping</code> spezialisiert <code>DiagnosticSwMapping</code> (abgeleitet von <code>DiagnosticMapping</code> und <code>DiagnosticCommonElement</code> / <code>ARElement</code>).</p>\n<p class=\"fig-p\"><code>DiagnosticIndicatorPortMapping</code> verfügt über drei Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>+indicator</code> (Multiplizität <code>1</code>) zum Modellelement <code>DiagnosticIndicator</code> (Spezialisierung von <code>DiagnosticCommonElement</code>).</li>\n<li><code>+process</code> (Multiplizität <code>0..1</code>, Stereotyp <code>«atpSplitable»</code>) zu <code>ProcessDesign</code> (<code>ARElement</code>), welches über <code>+design</code> (<code>0..1</code>) mit <code>Process</code> (<code>AbstractExecutionContext</code>) verbunden ist.</li>\n<li><code>+rPortPrototypeInExecutable</code> (Multiplizität <code>0..1</code>, Stereotypen <code>«instanceRef,atpUriDef»</code>) direkt zu <code>RPortPrototype</code> (Spezialisierung von <code>AbstractRequiredPortPrototype</code>).</li>\n</ul>\n<p class=\"fig-p\"><code>RPortPrototype</code> steht über <code>«isOfType» +requiredInterface</code> (Multiplizität <code>0..1</code>, Eigenschaft <code>{redefines atpType}</code>) in Beziehung zu <code>PortInterface</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>), welches über <code>DiagnosticPortInterface</code> zu <code>DiagnosticIndicatorInterface</code> spezialisiert wird.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die statische Zuordnungsstruktur: Zur Laufzeitkonfiguration verweist ein <code>DiagnosticIndicatorPortMapping</code> auf die funktionale Diagnose-Anforderungsdefinition (<code>DiagnosticIndicatorNeeds</code> über die Instanzreferenz auf <code>SwcServiceDependency</code>) und ordnet diese dem ausführenden Prozesskontext (<code>ProcessDesign</code> / <code>Process</code>) sowie dem logischen Diagnose-Indikator zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegungen:</p>\n<ul class=\"fig-list\">\n<li>Die Anbindung an den Port des Executables erfolgt unmittelbar über die Instanzreferenz <code>+rPortPrototypeInExecutable</code> unter Verwendung von <code>«instanceRef,atpUriDef»</code>.</li>\n<li>Die Indikatorzuordnung erfordert weiterhin zwingend ein <code>DiagnosticIndicator</code>-Element (<code>+indicator 1</code>).</li>\n<li>Attribute an <code>DiagnosticIndicator</code> und <code>Process</code> sind aus diesem Metamodellausschnitt vollständig entfernt.</li>\n</ul>"}, {"id": "FIG-f6d189b30484f893", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Klassendiagramm stellt das vereinfachte Metamodell für <code>DiagnosticIndicatorPortMapping</code> auf der AUTOSAR Adaptive Platform dar. Die Zuordnung verbindet das Diagnose-Port-Mapping direkt mit dem Required-Port des Executables (<code>RPortPrototype</code>) und dem Diagnose-Indikator, entkoppelt von der <code>SwcServiceDependency</code>- und <code>ServiceNeeds</code>-Hierarchie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><code>DiagnosticIndicatorPortMapping</code> spezialisiert <code>DiagnosticSwMapping</code> (abgeleitet von <code>DiagnosticMapping</code> und <code>DiagnosticCommonElement</code> / <code>ARElement</code>).</p>\n<p class=\"fig-p\"><code>DiagnosticIndicatorPortMapping</code> verfügt über drei Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>+indicator</code> mit Multiplizität <code>0..1</code> zum Modellelement <code>DiagnosticIndicator</code> (Spezialisierung von <code>DiagnosticCommonElement</code>).</li>\n<li><code>+process</code> mit Multiplizität <code>0..1</code> (Stereotyp <code>«atpSplitable»</code>) zu <code>ProcessDesign</code> (<code>ARElement</code>), welches über <code>+design</code> (<code>0..1</code>) mit <code>Process</code> (<code>AbstractExecutionContext</code>) verbunden ist.</li>\n<li><code>+rPortPrototypeInExecutable</code> mit Multiplizität <code>0..1</code> (Stereotypen <code>«instanceRef,atpUriDef»</code>) zu <code>RPortPrototype</code> (Spezialisierung von <code>AbstractRequiredPortPrototype</code>).</li>\n</ul>\n<p class=\"fig-p\"><code>RPortPrototype</code> referenziert über <code>«isOfType» +requiredInterface</code> (Multiplizität <code>0..1</code>, Eigenschaft <code>{redefines atpType}</code>) das <code>PortInterface</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>), welches über <code>DiagnosticPortInterface</code> zu <code>DiagnosticIndicatorInterface</code> spezialisiert wird.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die statische Zuordnungsstruktur: Zur Laufzeitkonfiguration verweist ein <code>DiagnosticIndicatorPortMapping</code> auf die funktionale Diagnose-Anforderungsdefinition (<code>DiagnosticIndicatorNeeds</code> über die Instanzreferenz auf <code>SwcServiceDependency</code>) und ordnet diese dem ausführenden Prozesskontext (<code>ProcessDesign</code> / <code>Process</code>) sowie dem logischen Diagnose-Indikator zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Wesentliche normative Änderung für Modellierer:</p>\n<ul class=\"fig-list\">\n<li>Die Referenz <code>+indicator</code> von <code>DiagnosticIndicatorPortMapping</code> auf <code>DiagnosticIndicator</code> ist optional (<code>0..1</code>), sodass ein Port-Mapping auch ohne unmittelbare Bindung an einen konkreten Indikator modelliert werden kann.</li>\n</ul>"}, {"id": "FIG-b7279f081ef8b0e8", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Klassendiagramm stellt das vereinfachte Metamodell für <code>DiagnosticIndicatorPortMapping</code> auf der AUTOSAR Adaptive Platform dar. Die Zuordnung verbindet das Diagnose-Port-Mapping direkt mit dem Required-Port des Executables (<code>RPortPrototype</code>) und dem Diagnose-Indikator, entkoppelt von der <code>SwcServiceDependency</code>- und <code>ServiceNeeds</code>-Hierarchie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><code>DiagnosticIndicatorPortMapping</code> spezialisiert <code>DiagnosticSwMapping</code> (abgeleitet von <code>DiagnosticMapping</code> und <code>DiagnosticCommonElement</code> / <code>ARElement</code>).</p>\n<p class=\"fig-p\"><code>DiagnosticIndicatorPortMapping</code> verfügt über drei Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>+indicator</code> mit Multiplizität <code>0..1</code> zum Modellelement <code>DiagnosticIndicator</code> (Spezialisierung von <code>DiagnosticCommonElement</code>).</li>\n<li><code>+process</code> mit Multiplizität <code>0..1</code> (Stereotyp <code>«atpSplitable»</code>) zu <code>ProcessDesign</code> (<code>ARElement</code>), welches über <code>+design</code> (<code>0..1</code>) mit <code>Process</code> (<code>AbstractExecutionContext</code>) verbunden ist.</li>\n<li><code>+rPortPrototypeInExecutable</code> mit Multiplizität <code>0..1</code> (Stereotypen <code>«instanceRef,atpUriDef»</code>) zu <code>RPortPrototype</code> (Spezialisierung von <code>AbstractRequiredPortPrototype</code>).</li>\n</ul>\n<p class=\"fig-p\"><code>RPortPrototype</code> referenziert über <code>«isOfType» +requiredInterface</code> (Multiplizität <code>0..1</code>, Eigenschaft <code>{redefines atpType}</code>) das <code>PortInterface</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>), welches über <code>DiagnosticPortInterface</code> zu <code>DiagnosticIndicatorInterface</code> spezialisiert wird.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die statische Zuordnungsstruktur: Zur Laufzeitkonfiguration verweist ein <code>DiagnosticIndicatorPortMapping</code> auf die funktionale Diagnose-Anforderungsdefinition (<code>DiagnosticIndicatorNeeds</code> über die Instanzreferenz auf <code>SwcServiceDependency</code>) und ordnet diese dem ausführenden Prozesskontext (<code>ProcessDesign</code> / <code>Process</code>) sowie dem logischen Diagnose-Indikator zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Wesentliche normative Änderung für Modellierer:</p>\n<ul class=\"fig-list\">\n<li>Die Referenz <code>+indicator</code> von <code>DiagnosticIndicatorPortMapping</code> auf <code>DiagnosticIndicator</code> ist optional (<code>0..1</code>), sodass ein Port-Mapping auch ohne unmittelbare Bindung an einen konkreten Indikator modelliert werden kann.</li>\n</ul>"}, {"id": "FIG-170b97aa72cbc71c", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Klassendiagramm stellt das vereinfachte Metamodell für <code>DiagnosticIndicatorPortMapping</code> auf der AUTOSAR Adaptive Platform dar. Die Zuordnung verbindet das Diagnose-Port-Mapping direkt mit dem Required-Port des Executables (<code>RPortPrototype</code>) und dem Diagnose-Indikator, entkoppelt von der <code>SwcServiceDependency</code>- und <code>ServiceNeeds</code>-Hierarchie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><code>DiagnosticIndicatorPortMapping</code> spezialisiert <code>DiagnosticSwMapping</code> (abgeleitet von <code>DiagnosticMapping</code> und <code>DiagnosticCommonElement</code> / <code>ARElement</code>).</p>\n<p class=\"fig-p\"><code>DiagnosticIndicatorPortMapping</code> verfügt über drei Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>+indicator</code> mit Multiplizität <code>0..1</code> zum Modellelement <code>DiagnosticIndicator</code> (Spezialisierung von <code>DiagnosticCommonElement</code>).</li>\n<li><code>+process</code> mit Multiplizität <code>0..1</code> (Stereotyp <code>«atpSplitable»</code>) zu <code>ProcessDesign</code> (<code>ARElement</code>), welches über <code>+design</code> (<code>0..1</code>) mit <code>Process</code> (<code>AbstractExecutionContext</code>) verbunden ist.</li>\n<li><code>+rPortPrototypeInExecutable</code> mit Multiplizität <code>0..1</code> (Stereotypen <code>«instanceRef,atpUriDef»</code>) zu <code>RPortPrototype</code> (Spezialisierung von <code>AbstractRequiredPortPrototype</code>).</li>\n</ul>\n<p class=\"fig-p\"><code>RPortPrototype</code> referenziert über <code>«isOfType» +requiredInterface</code> (Multiplizität <code>0..1</code>, Eigenschaft <code>{redefines atpType}</code>) das <code>PortInterface</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>), welches über <code>DiagnosticPortInterface</code> zu <code>DiagnosticIndicatorInterface</code> spezialisiert wird.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die statische Zuordnungsstruktur: Zur Laufzeitkonfiguration verweist ein <code>DiagnosticIndicatorPortMapping</code> auf die funktionale Diagnose-Anforderungsdefinition (<code>DiagnosticIndicatorNeeds</code> über die Instanzreferenz auf <code>SwcServiceDependency</code>) und ordnet diese dem ausführenden Prozesskontext (<code>ProcessDesign</code> / <code>Process</code>) sowie dem logischen Diagnose-Indikator zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Wesentliche normative Änderung für Modellierer:</p>\n<ul class=\"fig-list\">\n<li>Die Referenz <code>+indicator</code> von <code>DiagnosticIndicatorPortMapping</code> auf <code>DiagnosticIndicator</code> ist optional (<code>0..1</code>), sodass ein Port-Mapping auch ohne unmittelbare Bindung an einen konkreten Indikator modelliert werden kann.</li>\n</ul>"}, {"id": "FIG-22cbc552da2c1480", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Klassendiagramm stellt das vereinfachte Metamodell für <code>DiagnosticIndicatorPortMapping</code> auf der AUTOSAR Adaptive Platform dar. Die Zuordnung verbindet das Diagnose-Port-Mapping direkt mit dem Required-Port des Executables (<code>RPortPrototype</code>) und dem Diagnose-Indikator, entkoppelt von der <code>SwcServiceDependency</code>- und <code>ServiceNeeds</code>-Hierarchie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><code>DiagnosticIndicatorPortMapping</code> spezialisiert <code>DiagnosticSwMapping</code> (abgeleitet von <code>DiagnosticMapping</code> und <code>DiagnosticCommonElement</code> / <code>ARElement</code>).</p>\n<p class=\"fig-p\"><code>DiagnosticIndicatorPortMapping</code> verfügt über drei Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><code>+indicator</code> mit Multiplizität <code>0..1</code> zum Modellelement <code>DiagnosticIndicator</code> (Spezialisierung von <code>DiagnosticCommonElement</code>).</li>\n<li><code>+process</code> mit Multiplizität <code>0..1</code> (Stereotyp <code>«atpSplitable»</code>) zu <code>ProcessDesign</code> (<code>ARElement</code>), welches über <code>+design</code> (<code>0..1</code>) mit <code>Process</code> (<code>AbstractExecutionContext</code>) verbunden ist.</li>\n<li><code>+rPortPrototypeInExecutable</code> mit Multiplizität <code>0..1</code> (Stereotypen <code>«instanceRef,atpUriDef»</code>) zu <code>RPortPrototype</code> (Spezialisierung von <code>AbstractRequiredPortPrototype</code>).</li>\n</ul>\n<p class=\"fig-p\"><code>RPortPrototype</code> referenziert über <code>«isOfType» +requiredInterface</code> (Multiplizität <code>0..1</code>, Eigenschaft <code>{redefines atpType}</code>) das <code>PortInterface</code> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>), welches über <code>DiagnosticPortInterface</code> zu <code>DiagnosticIndicatorInterface</code> spezialisiert wird.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es definiert die statische Zuordnungsstruktur: Zur Laufzeitkonfiguration verweist ein <code>DiagnosticIndicatorPortMapping</code> auf die funktionale Diagnose-Anforderungsdefinition (<code>DiagnosticIndicatorNeeds</code> über die Instanzreferenz auf <code>SwcServiceDependency</code>) und ordnet diese dem ausführenden Prozesskontext (<code>ProcessDesign</code> / <code>Process</code>) sowie dem logischen Diagnose-Indikator zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Wesentliche normative Änderung für Modellierer:</p>\n<ul class=\"fig-list\">\n<li>Die Referenz <code>+indicator</code> von <code>DiagnosticIndicatorPortMapping</code> auf <code>DiagnosticIndicator</code> ist optional (<code>0..1</code>), sodass ein Port-Mapping auch ohne unmittelbare Bindung an einen konkreten Indikator modelliert werden kann.</li>\n</ul>"}], "trans": [{"from": "FIG-8cb385cd9a2cc803", "to": "FIG-ba3fba9edee8e634", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribut <code>DiagnosticIndicator.healingCycleCounterThreshold: PositiveInteger</code> entfernt</li>\n<li>Attribut <code>DiagnosticIndicator.type: DiagnosticIndicatorTypeEnum [0..1]</code> mit Stereotyp <code>«atpVariation»</code> versehen</li>\n<li>Attribut <code>Process.logTraceLogMode</code> von Multiplizität <code>[0..1]</code> auf <code>[0..*]</code> erweitert</li>\n<li>Attribut <code>Process.numberOfRestartAttempts: PositiveInteger [0..1]</code> hinzugefügt</li>\n</ul>"}, {"from": "FIG-ba3fba9edee8e634", "to": "FIG-eeb2eceb2b245eea", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>RoleBasedPortAssignment</code> mit Attribut <code>role: Identifier [0..1]</code> hinzugefügt und über Komposition <code>+assignedPort</code> (Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation,atpSplitable»</code>) an <code>SwcServiceDependency</code> angebunden</li>\n<li>Port-Klassenhierarchie ergänzt: <code>PortPrototype</code> (Spezialisierung von <code>AtpBlueprintable</code>, <code>AtpPrototype</code>), <code>AbstractRequiredPortPrototype</code>, <code>RPortPrototype</code> sowie Ziel-Assoziation <code>+portPrototype</code> mit Multiplizität <code>0..1</code> von <code>RoleBasedPortAssignment</code></li>\n<li>Schnittstellen-Klassenhierarchie ergänzt: <code>PortInterface</code> (Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>), <code>DiagnosticPortInterface</code> und <code>DiagnosticIndicatorInterface</code></li>\n<li>Assoziation <code>«isOfType»</code> von <code>RPortPrototype</code> auf <code>PortInterface</code> mit Rollenname <code>+requiredInterface</code>, Multiplizität <code>0..1</code> und Eigenschaft <code>{redefines atpType}</code> eingeführt</li>\n<li>Assoziation <code>+serviceNeeds</code> zwischen <code>SwcServiceDependency</code> und <code>ServiceNeeds</code> von Multiplizität <code>1</code> auf <code>0..1</code> gelockert</li>\n<li>Attribute <code>logTraceDefaultLogLevel</code>, <code>logTraceFilePath</code>, <code>logTraceLogMode</code>, <code>logTraceProcessDesc</code> und <code>logTraceProcessId</code> an <code>Process</code> entfernt</li>\n<li>Attribut <code>Process.functionClusterAffiliation: String [0..1]</code> ergänzt</li>\n</ul>"}, {"from": "FIG-eeb2eceb2b245eea", "to": "FIG-54eaaa4e5cd932df", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Service- und Portzuordnungsklassen <code>RoleBasedPortAssignment</code>, <code>SwcServiceDependency</code>, <code>ServiceNeeds</code>, <code>DiagnosticCapabilityElement</code> und <code>DiagnosticIndicatorNeeds</code> vollständig entfernt</li>\n<li>Direkte Instanzreferenz <code>+rPortPrototypeInExecutable</code> mit Stereotypen <code>«instanceRef,atpUriDef»</code> und Multiplizität <code>0..1</code> von <code>DiagnosticIndicatorPortMapping</code> auf <code>RPortPrototype</code> eingeführt</li>\n<li>Attribute <code>audience</code>, <code>diagRequirement</code> und <code>securityAccessLevel</code> an <code>DiagnosticCapabilityElement</code> entfallen durch Wegfall der Klasse</li>\n<li>Attribute <code>functionClusterAffiliation</code>, <code>numberOfRestartAttempts</code> und <code>preMapping</code> an <code>Process</code> entfernt</li>\n<li>Attribut <code>type</code> an <code>DiagnosticIndicator</code> entfernt</li>\n</ul>"}, {"from": "FIG-54eaaa4e5cd932df", "to": "FIG-f6d189b30484f893", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Multiplizität der Assoziation <code>+indicator</code> von <code>DiagnosticIndicatorPortMapping</code> zu <code>DiagnosticIndicator</code> von <code>1</code> auf <code>0..1</code> geändert</li>\n</ul>"}, {"from": "FIG-f6d189b30484f893", "to": "FIG-b7279f081ef8b0e8", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Diagrammlayout von Hochkant-/Blockanordnung auf horizontale Streckung umgestellt; Klassenboxen und Verbindungslinien neu platziert</li>\n</ul>"}, {"from": "FIG-b7279f081ef8b0e8", "to": "FIG-170b97aa72cbc71c", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-170b97aa72cbc71c", "to": "FIG-22cbc552da2c1480", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
